/** Die Einheit einer Zone, oder null, wenn die Stadt oder der Schlüssel unbekannt ist. */
export function unitOfZone(city: string, zoneKey: string): string | null {
  return ZONE_UNITS[city]?.[zoneKey] ?? null
}
